    public static function svg(string $name, string $class = ''): HtmlString
    {
        $cls = trim('ic ' . $class);

        if (isset(self::FILLED[$name])) {
            return new HtmlString('<svg class="' . e($cls) . '" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">' . self::FILLED[$name] . '</svg>');
        }

        $paths = self::PATHS[$name] ?? self::PATHS['sparkles'];

        return new HtmlString('<svg class="' . e($cls) . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' . $paths . '</svg>');
    }
